      defs.map(d=>'<div class="lead-row"><span>'+escapeHtml(d.label)+'</span><input class="lead-cf-inp" type="'+inputType(d.type)+'" value="'+escapeHtml(cf[d.key]||'')+'" onchange="liveCustomSave(\''+card.id+'\',\''+d.key+'\',this.value)"></div>').join('');
