function normalizeEmailTemplate(tpl) {
  const baseDesigner = defaultEmailDesigner();
  const designer = { ...baseDesigner, ...((tpl && tpl.designer && typeof tpl.designer === 'object') ? tpl.designer : {}) };
  if (!designer.logoData) designer.logoData = baseDesigner.logoData || '';
  if (!designer.brandName) designer.brandName = baseDesigner.brandName || 'Virando a Chave';
  return {
    ...tpl,
    name: tpl?.name || 'Template Virando a Chave',
    subject: tpl?.subject || designer.subject || baseDesigner.subject,
    designer,
    html: tpl?.html || renderEmailDesignerHtml(designer),
  };
}
function getFallbackEmailTemplates() {
  const designer = defaultEmailDesigner();
  return [normalizeEmailTemplate({
    id: 'tpl-nike-fallback',
    name: 'Template Nike Virando a Chave',
    subject: designer.subject,
    designer,
    html: renderEmailDesignerHtml(designer),
    updatedAt: Date.now(),
  })];
}
function withTimeout(promise, ms) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms))
  ]);
}
function renderEmailInboxItems(msgs, opts) {
  const list = document.getElementById('email-list'); if (!list) return;
  const syncing = !!opts?.syncing;
  const folder = opts?.folder === 'trash' ? 'trash' : (opts?.folder === 'sent' ? 'sent' : 'inbox');
  if (!Array.isArray(msgs) || !msgs.length) {
    list.innerHTML = syncing
      ? '<div class="email-empty">Sincronizando ' + (folder === 'trash' ? 'lixeira' : (folder === 'sent' ? 'enviados' : 'caixa de entrada')) + '…</div>'
      : '<div class="email-empty">Nenhum email.</div>';
    return;
  }
  const syncBanner = syncing ? '<div class="email-syncing">Atualizando emails…</div>' : '';
  list.innerHTML = syncBanner + msgs.map(m => `<div class="email-item ${m.seen ? '' : 'unread'}" data-uid="${m.uid}"><div class="email-item-top"><span class="email-from">${escapeHtml(m.fromName || m.from)}</span><span class="email-date">${fmtEmailDate(m.date)}</span></div><div class="email-subj">${escapeHtml(m.subject)}</div></div>`).join('');
  list.querySelectorAll('.email-item').forEach(el => el.addEventListener('click', () => openEmailMessage(el.dataset.uid, el, folder)));
}
function emailHomePct(value, total) {
  return total ? Math.round((Number(value || 0) / Number(total || 0)) * 100) : 0;
}
function emailHomeDate(value) {
  if (!value) return 'Sem data';
  try { return new Date(Number(value)).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }); } catch (e) { return 'Sem data'; }
}
function emailHomeStatus(status) {
  const map = { enviada: 'Enviada', agendada: 'Agendada', enviando: 'Enviando', rascunho: 'Rascunho' };
  return map[status] || 'Rascunho';
}
async function loadEmailHome() {
  const perf = document.getElementById('email-home-performance');
  const audience = document.getElementById('email-home-audience-card');
  const recent = document.getElementById('email-home-recent');
  if (!perf || !audience || !recent) return;
  const getJson = async path => {
    try {
      const response = await withTimeout(apiFetch(path), 3500);
      if (!response.ok) return [];
      const data = await response.json();
      return Array.isArray(data) ? data : (Array.isArray(data?.campaigns) ? data.campaigns : (Array.isArray(data?.templates) ? data.templates : []));
    } catch (e) { return []; }
  };
  const [campaigns, clients, templates] = await Promise.all([
    getJson('/api/email/campaigns'),
    getJson('/api/email/clients'),
    getJson('/api/email/templates'),
  ]);
  const totalSent = campaigns.reduce((sum, campaign) => sum + Number(campaign?.stats?.sent || 0), 0);
  const totalOpened = campaigns.reduce((sum, campaign) => sum + Number(campaign?.stats?.opened || 0), 0);
  const totalClicked = campaigns.reduce((sum, campaign) => sum + Number(campaign?.stats?.clicked || 0), 0);
  const scheduled = campaigns.filter(campaign => campaign?.status === 'agendada').length;
  const recipientSet = new Set();
  clients.forEach(client => Object.values(client?.groups || {}).forEach(group => {
    (Array.isArray(group) ? group : []).forEach(email => { if (email) recipientSet.add(String(email).trim().toLowerCase()); });
  }));
  const metric = (label, value, note) => '<article class="email-home-metric"><span>' + label + '</span><strong>' + value + '</strong><small>' + note + '</small></article>';
  perf.innerHTML = [
    metric('Emails enviados', totalSent.toLocaleString('pt-BR'), campaigns.length ? 'em ' + campaigns.length + ' campanha' + (campaigns.length === 1 ? '' : 's') : 'nenhuma campanha criada'),
    metric('Taxa de abertura', emailHomePct(totalOpened, totalSent) + '%', totalOpened.toLocaleString('pt-BR') + ' abertura' + (totalOpened === 1 ? '' : 's')),
    metric('Taxa de clique', emailHomePct(totalClicked, totalSent) + '%', totalClicked.toLocaleString('pt-BR') + ' clique' + (totalClicked === 1 ? '' : 's')),
    metric('Agendadas', scheduled.toLocaleString('pt-BR'), scheduled ? 'aguardando o envio' : 'nenhum envio agendado'),
  ].join('');
  audience.innerHTML = '<div class="email-home-audience-number">' + recipientSet.size.toLocaleString('pt-BR') + '</div>'
    + '<div><b>contato' + (recipientSet.size === 1 ? '' : 's') + ' cadastrado' + (recipientSet.size === 1 ? '' : 's') + '</b><p>' + clients.length.toLocaleString('pt-BR') + ' cliente' + (clients.length === 1 ? '' : 's') + ' com base de emails configurável.</p></div>'
    + '<button type="button" class="email-home-inline-action" onclick="switchEmailView(\'settings\')">Gerenciar público</button>';
  const ordered = campaigns.slice().sort((a, b) => Number(b.sentAt || b.scheduledFor || b.createdAt || 0) - Number(a.sentAt || a.scheduledFor || a.createdAt || 0)).slice(0, 4);
  recent.innerHTML = ordered.length ? ordered.map(campaign => {
    const stats = campaign?.stats || {};
    return '<button type="button" class="email-home-recent-row" onclick="window.emailHomeOpenCampaign(\'' + escapeAttr(campaign.id || '') + '\')">'
      + '<span class="email-home-recent-main"><b>' + escapeHtml(campaign.name || 'Campanha sem nome') + '</b><small>' + escapeHtml(campaign.subject || 'Sem assunto') + ' · ' + emailHomeDate(campaign.sentAt || campaign.scheduledFor || campaign.createdAt) + '</small></span>'
      + '<span class="email-home-status is-' + escapeAttr(campaign.status || 'rascunho') + '">' + emailHomeStatus(campaign.status) + '</span>'
      + '<span class="email-home-recent-stat">' + Number(stats.sent || 0).toLocaleString('pt-BR') + '<small>enviados</small></span>'
      + '</button>';
  }).join('') : '<div class="email-home-empty"><b>Nenhuma campanha ainda.</b><span>Crie a primeira para acompanhar os resultados aqui.</span><button type="button" onclick="window.emailHomeCreateCampaign()">Criar campanha</button></div>';
  if (templates.length && !_emailTemplates.length) _emailTemplates = templates.map(normalizeEmailTemplate).filter(Boolean);
}
function setEmailViewTitle(view) {
  const titleMap = {
    home: 'Início',
    inbox: 'Caixa de entrada',
    drafts: 'Com estrela',
    scheduled: 'Adiados',
    sent: 'Enviados',
    spam: 'Spam',
    trash: 'Lixeira',
    templates: 'Templates',
    settings: 'Configurações',
  };
  const el = document.getElementById('email-view-title');
  if (el) el.textContent = titleMap[view] || 'Email';
  const btn = document.getElementById('email-new-template-btn');
  if (btn) btn.style.display = view === 'templates' ? '' : 'none';
}
function activateEmailPane(id) {
  document.querySelectorAll('#tab-email .email-pane').forEach(el => el.classList.remove('active'));
  document.getElementById(id)?.classList.add('active');
}
function closeEmailMessageView() {
  document.getElementById('email-inbox-layout')?.classList.remove('reading');
  document.querySelectorAll('#tab-email .email-item.active').forEach(x => x.classList.remove('active'));
}
function renderEmailPlaceholder(view) {
  const list = document.getElementById('email-list');
  const pane = document.getElementById('email-read');
  const labels = { drafts: 'Com estrela', scheduled: 'Adiados', sent: 'Enviados', spam: 'Spam', trash: 'Lixeira' };
  if (list) list.innerHTML = `<div class="email-empty">${labels[view] || 'Área em breve'}</div>`;
  if (pane) pane.innerHTML = `<div class="email-placeholder-view">A área de ${labels[view] || 'Email'} fica aqui dentro da nova distribuição do Email.</div>`;
}
async function switchEmailView(view) {
  _emailView = view;
  document.querySelectorAll('#tab-email [data-email-view]').forEach(el => el.classList.toggle('active', el.dataset.emailView === view));
  setEmailViewTitle(view);
  if (view === 'home') {
    activateEmailPane('email-pane-home');
    loadEmailHome();
    return;
  }
  if (view === 'templates') {
    activateEmailPane('email-pane-templates');
    await loadEmailTemplates();
    return;
  }
  if (view === 'settings') {
    activateEmailPane('email-pane-settings');
    await Promise.all([loadEmailConfig(), loadEmailClients()]);
    return;
  }
  activateEmailPane('email-pane-inbox');
  closeEmailMessageView();
  if (view === 'inbox') {
    loadEmailInbox({ silent: true, folder: 'inbox' });
    return;
  }
  if (view === 'sent') {
    loadEmailInbox({ silent: true, folder: 'sent' });
    return;
  }
  if (view === 'trash') {
    loadEmailInbox({ silent: true, folder: 'trash' });
    return;
  }
  renderEmailPlaceholder(view);
}
async function updateEmailNav() {
  try {
    const r = await apiFetch('/api/email/status'+(_emailAccountId?'?accountId='+encodeURIComponent(_emailAccountId):'')); const d = await r.json();
    _emailAccounts=Array.isArray(d.accounts)?d.accounts:_emailAccounts;if(!_emailAccountId&&d.account?.id){_emailAccountId=d.account.id;localStorage.setItem('vac-email-account',_emailAccountId)}
    const nav = document.getElementById('nav-email');
    _emailConfigured = !!d.configured;
    if (nav) nav.style.display = '';
    const sub = document.getElementById('email-acct-sub');
    if (sub) sub.textContent = d.configured ? (d.user || 'Caixa de entrada') : 'Configure a caixa de email';
    if (!_emailNavReady) {
      _emailNavReady = true;
      document.getElementById('email-compose-btn')?.addEventListener('click', () => emailCompose());
      document.getElementById('email-refresh-btn')?.addEventListener('click', () => {
        if (_emailView === 'home') return loadEmailHome();
        if (_emailView === 'templates') return loadEmailTemplates();
        if (_emailView === 'settings') return Promise.all([loadEmailConfig(), loadEmailClients()]);
        return loadEmailInbox({ folder: _emailView === 'trash' ? 'trash' : (_emailView === 'sent' ? 'sent' : 'inbox') });
      });
      document.getElementById('email-new-template-btn')?.addEventListener('click', () => openEmailTemplateEditor());
      document.querySelectorAll('#tab-email [data-email-view]').forEach(btn => btn.addEventListener('click', () => switchEmailView(btn.dataset.emailView || 'inbox')));
      document.getElementById('email-save-config-btn')?.addEventListener('click', saveEmailConfig);
      document.getElementById('email-ms-connect-btn')?.addEventListener('click', connectMicrosoftEmail);
      document.getElementById('email-ms-save-app-btn')?.addEventListener('click', saveMicrosoftEmailApp);
      document.getElementById('email-add-imap-btn')?.addEventListener('click', newImapEmailAccount);
      document.getElementById('email-remove-account-btn')?.addEventListener('click', removeEmailAccount);
      document.getElementById('email-account-select')?.addEventListener('change',e=>selectEmailAccount(e.target.value));
      document.getElementById('email-save-client-btn')?.addEventListener('click', saveEmailClientSettings);
      document.getElementById('email-client-select')?.addEventListener('change', e => fillEmailClientFields(e.target.value));
      document.getElementById('email-home-compose')?.addEventListener('click', () => emailCompose());
      document.getElementById('email-home-new-campaign')?.addEventListener('click', () => window.emailHomeCreateCampaign());
      document.getElementById('email-home-campaign-quick')?.addEventListener('click', () => window.emailHomeCreateCampaign());
      document.getElementById('email-home-audience')?.addEventListener('click', () => switchEmailView('settings'));
      document.getElementById('email-home-templates')?.addEventListener('click', () => switchEmailView('templates'));
      document.getElementById('email-home-analytics')?.addEventListener('click', () => window.emailHomeOpenMarketing('analises'));
      document.getElementById('email-home-audience-link')?.addEventListener('click', () => switchEmailView('settings'));
      document.getElementById('email-home-campaigns-link')?.addEventListener('click', () => window.emailHomeOpenMarketing('campanhas'));
    }
    if (d.configured && !_emailPreloadStarted) {
      _emailPreloadStarted = true;
      const cached = readEmailInboxCache('inbox');
      if (cached.length) _emailInboxHydrated.inbox = true;
      loadEmailInbox({ silent: true, folder: 'inbox' });
    }
    if (_emailView === 'home') loadEmailHome();
  } catch (e) {}
}
function fmtEmailDate(d) {
  try { const dt = new Date(d); const now = new Date(); const same = dt.toDateString() === now.toDateString();
    return same ? dt.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) : dt.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }); } catch (e) { return ''; }
}
async function loadEmailInbox(opts) {
  const list = document.getElementById('email-list'); if (!list) return;
  if (!_emailConfigured) {
    list.innerHTML = '<div class="email-empty">Configure a caixa de email em Configurações para começar.</div>';
    const pane = document.getElementById('email-read');
    if (pane) pane.innerHTML = '<div class="email-placeholder-view">Depois da configuração, sua caixa de entrada aparece aqui.</div>';
    return;
  }
  const silent = !!opts?.silent;
  const folder = opts?.folder === 'trash' ? 'trash' : (opts?.folder === 'sent' ? 'sent' : 'inbox');
  const cached = readEmailInboxCache(folder);
  if (cached.length && !_emailInboxHydrated[folder]) {
    _emailInboxHydrated[folder] = true;
    renderEmailInboxItems(cached, { syncing: true, folder });
  } else if (!cached.length && !silent) {
    list.innerHTML = '<div class="email-loading">Carregando emails…</div>';
  } else if (cached.length) {
    renderEmailInboxItems(cached, { syncing: true, folder });
  }
  try {
    const r = await apiFetch('/api/email/inbox?limit=40&folder=' + folder + emailAccountQuery());
    if (!r.ok) { list.innerHTML = '<div class="email-empty">Erro ao carregar a caixa.</div>'; return; }
    const msgs = await r.json();
    writeEmailInboxCache(msgs, folder);
    _emailInboxHydrated[folder] = true;
    renderEmailInboxItems(msgs, { syncing: false, folder });
  } catch (e) { list.innerHTML = '<div class="email-empty">Erro ao carregar a caixa.</div>'; }
}
async function openEmailMessage(uid, el, folder) {
  const pane = document.getElementById('email-read'); if (!pane) return;
  document.getElementById('email-inbox-layout')?.classList.add('reading');
  pane.innerHTML = '<div class="email-loading">Abrindo…</div>';
  if (el) { document.querySelectorAll('.email-item.active').forEach(x => x.classList.remove('active')); el.classList.add('active'); el.classList.remove('unread'); }
  try {
    folder = folder === 'trash' ? 'trash' : (folder === 'sent' ? 'sent' : 'inbox');
    const r = await apiFetch('/api/email/message/' + encodeURIComponent(uid) + '?folder=' + folder + emailAccountQuery());
    if (!r.ok) { pane.innerHTML = '<div class="email-empty">Erro ao abrir o email.</div>'; return; }
    const m = await r.json();
    const replyTo = encodeURIComponent(m.from || '');
    const replySubj = encodeURIComponent(m.subject || '');
    pane.innerHTML = `<div class="email-head"><button class="email-back-btn" id="email-back-btn">Voltar para emails</button><div class="email-head-subj">${escapeHtml(m.subject)}</div><div class="email-head-row"><div class="email-head-meta"><b>${escapeHtml(m.from)}</b><span class="email-head-date">${fmtEmailDate(m.date)}</span></div><div class="email-head-actions"><button class="email-delete-btn" id="email-delete-btn">${folder === 'trash' ? 'Excluir definitivamente' : 'Excluir'}</button><button class="email-reply-btn" onclick="emailReplyEnc('${replyTo}','${replySubj}')">Responder</button></div></div></div><div class="email-body">${m.html ? '<iframe class="email-iframe" sandbox="allow-popups allow-same-origin"></iframe>' : ('<pre class="email-text">' + escapeHtml(m.text || '') + '</pre>')}</div>`;
    pane.querySelector('#email-back-btn')?.addEventListener('click', closeEmailMessageView);
    pane.querySelector('#email-delete-btn')?.addEventListener('click', () => deleteEmailMessage(uid, folder));
    if (m.html) { const ifr = pane.querySelector('.email-iframe'); if (ifr) ifr.srcdoc = m.html; }
  } catch (e) { pane.innerHTML = '<div class="email-empty">Erro ao abrir o email.</div>'; }
}
async function deleteEmailMessage(uid, folder) {
  const permanent = folder === 'trash';
  const question = permanent
    ? 'Excluir este email definitivamente? Esta ação não pode ser desfeita.'
    : 'Mover este email para a Lixeira?';
  if (!uid || !confirm(question)) return;
  const btn = document.getElementById('email-delete-btn');
  if (btn) { btn.disabled = true; btn.textContent = permanent ? 'Excluindo…' : 'Movendo…'; }
  try {
    const r = await apiFetch('/api/email/message/' + encodeURIComponent(uid) + '?folder=' + folder + emailAccountQuery(), { method: 'DELETE' });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(data.error || 'Não foi possível excluir o email.');
    closeEmailMessageView();
    _emailInboxHydrated[folder] = false;
    await loadEmailInbox({ folder });
  } catch (e) {
    alert(e.message || 'Não foi possível excluir o email.');
    if (btn) { btn.disabled = false; btn.textContent = permanent ? 'Excluir definitivamente' : 'Excluir'; }
  }
}
async function loadEmailTemplates() {
  const grid = document.getElementById('email-templates-grid'); if (!grid) return;
  grid.innerHTML = '<div class="email-loading">Carregando templates…</div>';
  try {
    const r = await withTimeout(apiFetch('/api/email/templates'), 2500);
    if (!r.ok) {
      _emailTemplates = getFallbackEmailTemplates();
      renderEmailTemplates();
      return;
    }
    const payload = await r.json();
    const arr = Array.isArray(payload)
      ? payload
      : (Array.isArray(payload?.templates) ? payload.templates : []);
    _emailTemplates = (arr.length ? arr : getFallbackEmailTemplates()).map(normalizeEmailTemplate).filter(Boolean);
    renderEmailTemplates();
  } catch (e) {
    _emailTemplates = getFallbackEmailTemplates();
    renderEmailTemplates();
  }
}
function renderEmailTemplates() {
  const grid = document.getElementById('email-templates-grid'); if (!grid) return;
  if (!_emailTemplates.length) {
    _emailTemplates = getFallbackEmailTemplates();
  }
  if (!_emailTemplates.length) {
    grid.innerHTML = '<div class="email-empty">Nenhum template salvo.</div>';
    return;
  }
  grid.innerHTML = _emailTemplates.map(tpl => `
    <div class="email-template-card">
      <div class="email-template-name">${escapeHtml(tpl.name || 'Template')}</div>
      <div class="email-template-subject">Assunto: ${escapeHtml(tpl.subject || '(sem assunto)')}</div>
      <div class="email-template-preview">${escapeHtml(stripHtmlPreview(tpl.html || '')).slice(0, 220) || 'Sem conteúdo.'}</div>
      <div class="email-template-actions">
        <button class="email-template-btn" data-act="use" data-id="${escapeAttr(tpl.id)}">Usar</button>
        <button class="email-template-btn" data-act="edit" data-id="${escapeAttr(tpl.id)}">Designer</button>
        <button class="email-template-btn" data-act="delete" data-id="${escapeAttr(tpl.id)}">Excluir</button>
      </div>
    </div>
  `).join('');
  grid.querySelectorAll('[data-act="use"]').forEach(btn => btn.addEventListener('click', () => {
    const tpl = _emailTemplates.find(x => x.id === btn.dataset.id); emailCompose('', tpl?.subject || '', tpl || null);
  }));
  grid.querySelectorAll('[data-act="edit"]').forEach(btn => btn.addEventListener('click', () => {
    const tpl = _emailTemplates.find(x => x.id === btn.dataset.id); openEmailTemplateEditor(tpl);
  }));
  grid.querySelectorAll('[data-act="delete"]').forEach(btn => btn.addEventListener('click', () => deleteEmailTemplate(btn.dataset.id)));
}
async function deleteEmailTemplate(id) {
  if (!id || !confirm('Excluir este template?')) return;
  const r = await apiFetch('/api/email/templates/' + encodeURIComponent(id), { method: 'DELETE' });
  if (!r.ok) return alert('Não foi possível excluir o template.');
  loadEmailTemplates();
}
