async function removeEmailAccount(){if(!_emailAccountId)return;if(!confirm('Remover esta conta de email do SaaS? Os emails permanecem no provedor.'))return;const r=await apiFetch('/api/email/accounts/'+encodeURIComponent(_emailAccountId),{method:'DELETE'}),d=await r.json().catch(()=>({}));if(!r.ok)return alert(d.error||'Erro ao remover conta.');_emailAccountId=(d.accounts&&d.accounts[0]&&d.accounts[0].id)||'';localStorage.setItem('vac-email-account',_emailAccountId);loadEmailConfig();updateEmailNav();}
